create table IF NOT EXISTS blogComments(    comment_id varchar(36) not null,    commentP_id varchar(36) not null,    content text collate utf8_unicode_ci,    created_by varchar(36) not null,    activeFlag BOOLEAN,    addDate datetime not null,    primary key (comment_id))ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
create table IF NOT EXISTS blogCommentsLikes(    comment_id varchar(36) not null,    created_by varchar(36) not null,    addDate datetime not null,    primary key (comment_id))ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
create table IF NOT EXISTS blogCats(    cat_id varchar(36) not null,    catAlias varchar(256) not null,    catName_en varchar(256) not null,    catName_ru varchar(256) not null,    catMeta_en text collate utf8_unicode_ci,    catMeta_ru text collate utf8_unicode_ci,    catImg varchar(256),    activeFlag BOOLEAN,     indexFlag BOOLEAN,    created_by varchar(36) not null,     primary key (cat_id))ENGINE=MyISAM  DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
